// The dial starts at 1 (positions 0-3). Turning up past 3 overheats the heater, making the room permanently cold. Otherwise, the room is warm if the dial is at 1 or 2, and cold if it is at 0.
function visible(actions) {
  let dial = 1;
  let overheated = false;
  for (const action of actions) {
    if (action === "turn up") {
      dial = Math.min(dial + 1, 3);
    } else if (action === "turn down") {
      dial = Math.max(dial - 1, 0);
    }
    // "wait" leaves the dial unchanged
    if (dial === 3) {
      overheated = true;
    }
  }
  if (overheated) {
    return { room: "cold" };
  }
  return { room: (dial === 1 || dial === 2) ? "warm" : "cold" };
}

