function visible(actions) {
  let dial = 0;
  let primed = false;
  let lastAction = null;

  for (const action of actions) {
    if (action === "turn up") {
      dial = Math.min(2, dial + 1);
    } else if (action === "turn down") {
      dial = Math.max(0, dial - 1);
      if (dial === 0) primed = true;
    }
    lastAction = action;
  }

  let room;
  if (dial === 0) {
    room = "cold";
  } else if (dial === 2) {
    room = primed ? "warm" : "cold";
  } else {
    room = (primed || lastAction !== "turn down") ? "warm" : "cold";
  }

  return { room };
}

