// Explanation 1: A D-U-U pattern latches a hidden ready flag; otherwise a final D-U warms only if no U-U has occurred before that D.
function visible(actions) {
  let permanent = false;
  let seenUU = false;
  let lastD_atNoUU = false;

  for (let i = 0; i < actions.length; i++) {
    const a = actions[i];

    if (a === "turn up" && i >= 1 && actions[i - 1] === "turn up") {
      seenUU = true;
    }

    if (a === "turn down") {
      lastD_atNoUU = !seenUU;
    }

    if (
      a === "turn up" &&
      i >= 2 &&
      actions[i - 1] === "turn up" &&
      actions[i - 2] === "turn down"
    ) {
      permanent = true;
    }
  }

  const n = actions.length;
  const endsDU =
    n >= 2 &&
    actions[n - 2] === "turn down" &&
    actions[n - 1] === "turn up";

  return {
    room: permanent || (endsDU && lastD_atNoUU) ? "warm" : "cold"
  };
}

