  const n = actions.length;

  if (n >= 4) {
    const w = actions.slice(-4).join("|");
    const warm4 = [
      "turn down|turn up|turn up|turn down",
      "turn down|turn up|turn up|wait",
      "turn down|turn down|turn down|turn up"
